import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function exhibiting target ELA features.

    The function combines a skewed quadratic bowl, sinusoidal modulation with
    varying frequencies, and pairwise interactions.  The skew is introduced via a cubic term.
    The formula is approximately:

    f(x) = sum( (x_i^2 + 0.1*x_i^3) +  sin(2*pi*x_i) + 0.05*sum(x_i*x_j for j!=i)
    """
    n = len(x)
    result = 0.0

    for i in range(n):
        result += (x[i]**2 + 0.1 * x[i]**3) + np.sin(2 * np.pi * x[i])

    for i in range(n):
        for j in range(n):
            if i != j:
                result += 0.05 * x[i] * x[j]


    return float(result)
